const STORE_SECTION_CAPABILITY=Object.freeze({overview:TENANT_ADMIN_CAPABILITIES.dashboard,site:TENANT_ADMIN_CAPABILITIES.site,delivery:TENANT_ADMIN_CAPABILITIES.orders,menu:TENANT_ADMIN_CAPABILITIES.catalog,orders:TENANT_ADMIN_CAPABILITIES.orders,customers:TENANT_ADMIN_CAPABILITIES.customers,reviews:TENANT_ADMIN_CAPABILITIES.reviews,sales:TENANT_ADMIN_CAPABILITIES.sales,inventory:TENANT_ADMIN_CAPABILITIES.inventory,marketing:TENANT_ADMIN_CAPABILITIES.marketing,work:TENANT_ADMIN_CAPABILITIES.operations,finance:TENANT_ADMIN_CAPABILITIES.finance,connections:TENANT_ADMIN_CAPABILITIES.connections});
export function storeAdminCanAccess(role,section){const policy=tenantAdminPolicySnapshot();const allowed=policy.roleCapabilities[String(role||'').trim().toLowerCase()]||[];const capability=STORE_SECTION_CAPABILITY[String(section||'overview').toLowerCase()];return Boolean(capability&&(allowed.includes('*')||allowed.includes(capability)));}
export function storeAdminSectionsForRole(role){return Object.keys(STORE_SECTION_CAPABILITY).filter(section=>storeAdminCanAccess(role,section));}

